"use client";

import { AnimatePresence, animate, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a notification bell. The rest go to the button, such as `onClick`. */
export type NotificationBellProps = Omit<ComponentPropsWithoutRef<"button">, "children"> & {
  /** How many notifications are unread. Zero hides the badge. */
  count: number;
  /** Names the bell for screen readers. The unread count is added to it. */
  label?: string;
  /** The badge shows "99+" above this. */
  max?: number;
};

type Direction = 1 | -1;

// Damping 46 is 2 × √520, rounded up: critically damped, so digits land without overshoot.
const ROLL_SPRING: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
const POP: Transition = { type: "spring", duration: 0.3, bounce: 0 };
const FADE: Transition = { duration: 0.15 };
// The swing settles in smaller arcs, the way a struck bell does. It plays only
// when the count rises, so it marks something new and never loops.
const SWING = { rotate: [0, 14, -12, 8, -4, 0] };
const SWING_TIMING = { duration: 0.6, ease: "easeOut" } as const;

// The direction travels through AnimatePresence's `custom`, because a leaving
// number keeps the props of its last render and would exit the old way.
const ROLL = {
  enter: (dir: Direction) => ({ y: `${dir * 100}%`, opacity: 0 }),
  shown: { y: 0, opacity: 1 },
  leave: (dir: Direction) => ({ y: `${-dir * 100}%`, opacity: 0 }),
};
// Reduced motion keeps the change and drops the roll: the old number fades out as the new one fades in.
const CROSSFADE = { enter: { opacity: 0 }, shown: { opacity: 1 }, leave: { opacity: 0 } };

function BellGlyph() {
  return (
    <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" aria-hidden="true" className="size-5">
      <path
        d="M5 8.5a5 5 0 0 1 10 0c0 3.2.8 4.9 1.6 5.8.3.3.1.7-.3.7H3.7c-.4 0-.6-.4-.3-.7.8-.9 1.6-2.6 1.6-5.8Z"
        strokeLinejoin="round"
      />
      <path d="M8.2 17.2a2 2 0 0 0 3.6 0" strokeLinecap="round" />
    </svg>
  );
}

/**
 * A bell that shows how many notifications are unread. When the count rises,
 * the bell swings once and the number rolls up; when it falls, the number rolls down.
 */
export function NotificationBell({ count, label = "Notifications", max = 99, className, ...buttonProps }: NotificationBellProps) {
  const reduceMotion = useReducedMotion();
  const bell = useRef<HTMLSpanElement>(null);
  // A count that is not a whole number of notifications reads as none.
  const unread = Number.isFinite(count) ? Math.max(0, Math.floor(count)) : 0;
  const [previous, setPrevious] = useState(unread);
  const [direction, setDirection] = useState<Direction>(1);
  // The roll direction comes from the last count this bell rendered.
  if (unread !== previous) {
    setDirection(unread > previous ? 1 : -1);
    setPrevious(unread);
  }

  // Every new notification swings the bell, even once the badge is capped at "99+".
  const lastSwung = useRef(unread);
  useEffect(() => {
    const rose = unread > lastSwung.current;
    lastSwung.current = unread;
    if (rose && !reduceMotion && bell.current) animate(bell.current, SWING, SWING_TIMING);
  }, [unread, reduceMotion]);

  const shown = unread > max ? `${max}+` : String(unread);
  const name = unread > 0 ? `${label}, ${unread} unread` : label;

  return (
    <button
      {...buttonProps}
      type="button"
      aria-label={name}
      className={cn(
        "relative grid size-11 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-full text-foreground outline-none hover:bg-muted active:scale-95 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background motion-safe:transition motion-safe:duration-150 sm:size-10",
        className,
      )}
    >
      {/* The bell pivots from its top, where it would hang. */}
      <span ref={bell} className="flex origin-top">
        <BellGlyph />
      </span>
      <AnimatePresence initial={false}>
        {unread > 0 ? (
          <motion.span
            key="badge"
            aria-hidden="true"
            initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5 }}
            transition={reduceMotion ? FADE : POP}
            className="absolute right-0 top-0 flex h-4 min-w-4 items-center justify-center overflow-hidden rounded-full bg-primary px-1 text-xs font-semibold leading-none tabular-nums text-primary-foreground ring-2 ring-background"
          >
            <AnimatePresence mode="popLayout" initial={false} custom={direction}>
              <motion.span
                key={shown}
                custom={direction}
                variants={reduceMotion ? CROSSFADE : ROLL}
                initial="enter"
                animate="shown"
                exit="leave"
                transition={reduceMotion ? FADE : ROLL_SPRING}
                className="block"
              >
                {shown}
              </motion.span>
            </AnimatePresence>
          </motion.span>
        ) : null}
      </AnimatePresence>
    </button>
  );
}
